const initialProfile: Profile = { age: 25, gender:'', height:170, weight:70, goal:'افزایش قدرت', level:'مبتدی', pushups:0, squats:0, plank:0, experience:'تازه شروع می‌کنم', days:3, minutes:30, equipment:['بدون وسیله'], place:'خانه', focus:[], injury:[], dietary:'', sleep:'', activity:'' };
const goalsList = ['افزایش قدرت','عضله‌سازی','کاهش چربی','افزایش استقامت','حفظ تناسب اندام'];
const focusList = ['سینه','بازو','سرشانه','پشت','پا','میان‌تنه'];
const injuries = ['شانه','کمر','زانو','مچ','گردن'];
function planFor(profile: Profile, sessions: Session[]) {
  const level = profile.level === 'پیشرفته' ? 3 : profile.level === 'متوسط' ? 2 : 1;
  const safe = exercises.filter(e => e.group !== 'کشش' && e.group !== 'هوازی' && (e.gear === 'بدون وسیله' || profile.equipment.includes(e.gear)) && !(profile.injury.includes('شانه') && ['سینه','سرشانه','بازو'].includes(e.muscle)) && !(profile.injury.includes('زانو') && e.muscle === 'پا') && !(profile.injury.includes('کمر') && ['پشت','میان‌تنه'].includes(e.muscle)) && !(profile.injury.includes('مچ') && ['سینه','بازو'].includes(e.muscle)));
  const recent = sessions.slice(0,3);
  const progressing = recent.length >= 2 && recent.slice(0,2).every(s => s.effort <= 3 && s.effort > 0);
  const recovering = recent.length > 0 && recent[0].effort >= 5;
  const baseSets = recovering ? 1 : Math.min(4, (level === 1 ? 2 : level === 2 ? 3 : 4) + (progressing ? 1 : 0));
  const reps = recovering ? 6 : level === 1 ? 8 : level === 2 ? 10 : 12;
  const byGroup = (group: string) => safe.filter(e => e.muscle === group).sort((a,b) => (profile.focus.includes(b.muscle) ? 1 : 0) - (profile.focus.includes(a.muscle) ? 1 : 0) || Math.abs(a.level-level)-Math.abs(b.level-level));
  const chosen = [byGroup('پا')[0], byGroup('سینه')[0], byGroup('پشت')[0], byGroup('میان‌تنه')[0], byGroup('سرشانه')[0], byGroup('بازو')[0]].filter((e): e is Exercise => !!e).slice(0, profile.minutes < 25 ? 3 : profile.minutes < 40 ? 4 : 6);
  const duration = Math.min(profile.minutes, 5 + chosen.length * baseSets * (recovering ? 2 : 3) + 5);
  return { chosen, sets:baseSets, reps, rest:recovering ? 120 : level === 1 ? 90 : 60, duration, recovering, progressing };
}
function App() {
  const [data,setData] = useState<AppData>(load);
  const [view,setView] = useState<View>(() => load().profile ? 'home' : 'assessment');
  const [profileDraft,setProfileDraft] = useState<Profile>(() => load().profile || initialProfile);
  const [step,setStep] = useState(0);
  const [menu,setMenu] = useState(false);
  const [category,setCategory] = useState('همه');
  const [selectedExercise,setSelectedExercise] = useState<Exercise|null>(null);
  const [sessionOpen,setSessionOpen] = useState(false);
  const [checks,setChecks] = useState<Record<string,number>>({});
  const [effort,setEffort] = useState(3);
  const [sessionNote,setSessionNote] = useState('');
  const [meal,setMeal] = useState('صبحانه');
  const [foodText,setFoodText] = useState('');
  const [goalTitle,setGoalTitle] = useState('تعداد جلسه تمرین');
  const [goalTarget,setGoalTarget] = useState('12');
  const [goalDeadline,setGoalDeadline] = useState('');
  const [weightValue,setWeightValue] = useState('');
  const [confirmDelete,setConfirmDelete] = useState(false);
  const [cameraMode,setCameraMode] = useState<'pushup'|'curl'|null>(null);
  const [cameraTarget,setCameraTarget] = useState<number|undefined>(undefined);
  const today = dateKey();
  useEffect(() => { try { localStorage.setItem(STORAGE, JSON.stringify(data)); } catch { /* storage unavailable */ } },[data]);
  const profile = data.profile;
  const plan = useMemo(() => profile ? planFor(profile,data.sessions) : null,[profile,data.sessions]);
  const todaySessions = data.sessions.filter(s => s.date === today);
  const trainedToday = todaySessions.length > 0;
  const isScheduled = profile ? scheduledDays[profile.days]?.includes(jsToFaDay(new Date())) : false;
  const weekStart = new Date(); weekStart.setDate(weekStart.getDate() - jsToFaDay(weekStart));
  const weekStartKey = dateKey(weekStart);
  const weekly = data.sessions.filter(s => s.date >= weekStartKey);
  const totalMinutes = data.sessions.reduce((n,s) => n+s.minutes,0);
  const totalSets = data.sessions.reduce((n,s) => n+s.exercises.reduce((m,e) => m+e.done,0),0);
  const navigate = (v: View) => { setView(v); setMenu(false); setSelectedExercise(null); window.scrollTo({top:0,behavior:'smooth'}); };
  const updateProfile = <K extends keyof Profile>(key: K, value: Profile[K]) => setProfileDraft(p => ({...p,[key]:value}));
  const toggleValue = (key: 'equipment'|'focus'|'injury', value: string) => updateProfile(key, profileDraft[key].includes(value) ? profileDraft[key].filter(x => x !== value) : [...profileDraft[key],value]);
  const saveProfile = () => { setData(d => ({...d,profile:profileDraft,weightLogs: d.weightLogs.length ? d.weightLogs : [{date:today,value:profileDraft.weight}]})); navigate('home'); };
  const startSession = () => { setChecks({}); setEffort(3); setSessionNote(''); setSessionOpen(true); };
  const saveSession = () => { if (!plan) return; const completed = plan.chosen.filter(e => (checks[e.id]||0)>0).map(e => ({id:e.id,sets:plan.sets,reps:e.type === 'time' ? (e.id === 'plank' ? Math.max(15,Math.min(profile?.plank || 20,60)) : 30) : plan.reps,done:checks[e.id]})); if (!completed.length) return; const session: Session = { id:crypto.randomUUID(),date:today,exercises:completed,minutes:Math.max(5,Math.round(plan.duration * completed.reduce((n,e)=>n+e.done,0)/(plan.chosen.length*plan.sets))),effort,note:sessionNote.trim(),source:'manual' }; setData(d => ({...d,sessions:[session,...d.sessions]})); setSessionOpen(false); navigate('history'); };
  const openCamera = (mode: 'pushup'|'curl', target?: number) => { setCameraTarget(target); setCameraMode(mode); setSessionOpen(false); setSelectedExercise(null); };
  const saveCamera = (count: number) => { if (!cameraMode || count < 1) return; const id = cameraMode === 'pushup' ? 'pushup' : 'curl'; const session: Session = { id:crypto.randomUUID(),date:today,exercises:[{id,sets:1,reps:count,done:1}],minutes:0,effort:3,note:'ثبت تکرار با دوربین؛ نتیجهٔ تشخیص خودکار تقریبی است.',source:'camera' }; setData(d=>({...d,sessions:[session,...d.sessions]})); setCameraMode(null); navigate('records'); };
  const addFood = () => { if (!foodText.trim()) return; setData(d => ({...d,foods:[{id:crypto.randomUUID(),date:today,meal,text:foodText.trim()},...d.foods]})); setFoodText(''); };
  const addGoal = () => { const target = Number(goalTarget); if (!goalTitle.trim() || !Number.isFinite(target) || target <= 0 || !goalDeadline) return; setData(d => ({...d,goals:[...d.goals,{id:crypto.randomUUID(),title:goalTitle,target,deadline:goalDeadline,unit:goalTitle === 'تعداد جلسه تمرین' ? 'جلسه' : 'کیلوگرم'}]})); setGoalDeadline(''); };
  const levelLabel = profile ? (profile.level === 'مبتدی' && profile.pushups >= 20 && profile.squats >= 35 ? 'متوسط' : profile.level) : 'تازه‌وارد';
  const title: Record<View,string> = {home:'خانه',training:'برنامه تمرینی',body:'نقشه بدن',nutrition:'تغذیه',stats:'آمار و پیشرفت',assessment:'ارزیابی اولیه',library:'کتابخانه حرکات',history:'تاریخچه تمرین',goals:'اهداف شخصی',stretch:'قد و کشش',settings:'تنظیمات و اطلاعات',records:'رکورد شنا و دمبل',photos:'تغییر من'};
  return <div className="app-shell" dir="rtl">
    {view !== 'assessment' && <header className="topbar"><div className="container topbar-inner"><button className="brand" data-testid="brand-home" onClick={() => navigate('home')} aria-label="خانه"><span className="brand-mark"><Activity size={21} strokeWidth={3}/></span><span className="brand-type">DUEL<span>FIT</span><small>مسیر قوی‌تر شدن تو</small></span></button><nav className="desktop-nav"><button data-testid="nav-home-desktop" onClick={() => navigate('home')} className={view==='home'?'active':''}>خانه</button><button data-testid="nav-training-desktop" onClick={() => navigate('training')} className={view==='training'?'active':''}>برنامه تمرینی</button><button data-testid="nav-body-desktop" onClick={() => navigate('body')} className={view==='body'?'active':''}>نقشه بدن</button><button data-testid="nav-nutrition-desktop" onClick={() => navigate('nutrition')} className={view==='nutrition'?'active':''}>تغذیه</button><button data-testid="nav-stats-desktop" onClick={() => navigate('stats')} className={view==='stats'?'active':''}>پیشرفت</button></nav><button className="icon-btn" data-testid="menu-toggle" aria-label="باز کردن منو" onClick={() => setMenu(!menu)}>{menu?<X size={21}/>:<Menu size={21}/>}</button></div></header>}
    {menu && <div className="menu-backdrop" onClick={() => setMenu(false)}><div className="menu-panel" onClick={e => e.stopPropagation()}><div className="menu-head">دسترسی سریع <button data-testid="menu-close" onClick={() => setMenu(false)}><X size={20}/></button></div>{([['library','کتابخانه حرکات',Dumbbell],['stretch','قد و کشش',Waves],['goals','اهداف شخصی',Target],['history','تاریخچه تمرین',History],['records','رکورد شنا و دمبل',Dumbbell],['photos','تغییر من',Activity],['assessment','ویرایش ارزیابی',UserRound],['settings','تنظیمات',Settings2]] as const).map(([v,label,Icon]) => <button key={v} data-testid={`menu-${v}`} onClick={() => {if(v==='assessment'){setProfileDraft(profile || initialProfile);setStep(0)}navigate(v)}}><Icon size={19}/>{label}<ChevronLeft size={16}/></button>)}</div></div>}
    {view === 'assessment' ? <main className="assessment-wrap"><div className="assessment-layout"><aside className="assessment-aside"><div className="aside-glow"/><div className="brand brand-static"><span className="brand-mark"><Activity size={22} strokeWidth={3}/></span><span className="brand-type">DUEL<span>FIT</span></span></div><div><span className="eyebrow">شروع یک مسیر تازه</span><h1>برنامه‌ای که با <em>تو</em> شروع می‌شه.</h1><p>چند سؤال کوتاه کمک می‌کنه تمرین‌هات متناسب با توان و شرایط خودت چیده بشن.</p></div><div className="aside-note"><ShieldCheck size={20}/>اطلاعاتت فقط روی همین دستگاه ذخیره می‌شه.</div></aside><div className="assessment-main"><div className="form-top"><span>ارزیابی اولیه</span><span>مرحله {fa(step+1)} از ۴</span></div><div className="progress-track"><div style={{width:`${(step+1)*25}%`}}/></div>{step===0 && <div className="form-page"><span className="section-kicker">۰۱ / درباره تو</span><h2>اول کمی با هم آشنا بشیم</h2><p className="muted">این اطلاعات برای تنظیم فشار و زمان تمرین استفاده می‌شن.</p><div className="form-grid"><label>سن<input data-testid="profile-age" type="number" min="12" max="100" value={profileDraft.age} onChange={e=>updateProfile('age',Number(e.target.value))}/></label><label>جنسیت<select data-testid="profile-gender" value={profileDraft.gender} onChange={e=>updateProfile('gender',e.target.value)}><option value="">انتخاب کنید</option><option>زن</option><option>مرد</option><option>ترجیح می‌دهم نگویم</option></select></label><label>قد (سانتی‌متر)<input data-testid="profile-height" type="number" min="100" max="240" value={profileDraft.height} onChange={e=>updateProfile('height',Number(e.target.value))}/></label><label>وزن (کیلوگرم)<input data-testid="profile-weight" type="number" min="25" max="300" value={profileDraft.weight} onChange={e=>updateProfile('weight',Number(e.target.value))}/></label></div><div className="field-block"><strong>هدف اصلی‌ات چیه؟</strong><div className="choice-grid">{goalsList.map(g=><button type="button" data-testid={`goal-choice-${g}`} className={`choice ${profileDraft.goal===g?'chosen':''}`} onClick={()=>updateProfile('goal',g)} key={g}>{g}{profileDraft.goal===g&&<Check size={15}/>}</button>)}</div></div></div>}{step===1 && <div className="form-page"><span className="section-kicker">۰۲ / توان فعلی</span><h2>از کجا شروع می‌کنی؟</h2><p className="muted">عدد واقعی خودت رو وارد کن؛ صفر هم کاملاً طبیعیه.</p><div className="field-block"><strong>سطح فعلی</strong><div className="choice-grid">{['مبتدی','متوسط','پیشرفته'].map(x=><button data-testid={`level-${x}`} key={x} className={`choice ${profileDraft.level===x?'chosen':''}`} onClick={()=>updateProfile('level',x)}>{x}</button>)}</div></div><div className="form-grid"><label>تعداد شنای صحیح<input data-testid="profile-pushups" type="number" min="0" max="500" value={profileDraft.pushups} onChange={e=>updateProfile('pushups',Number(e.target.value))}/></label><label>تعداد اسکات صحیح<input data-testid="profile-squats" type="number" min="0" max="500" value={profileDraft.squats} onChange={e=>updateProfile('squats',Number(e.target.value))}/></label><label>مدت پلانک (ثانیه)<input data-testid="profile-plank" type="number" min="0" max="1800" value={profileDraft.plank} onChange={e=>updateProfile('plank',Number(e.target.value))}/></label><label>سابقه ورزشی<select data-testid="profile-experience" value={profileDraft.experience} onChange={e=>updateProfile('experience',e.target.value)}><option>تازه شروع می‌کنم</option><option>کمتر از ۱ سال</option><option>۱ تا ۳ سال</option><option>بیش از ۳ سال</option></select></label></div></div>}{step===2 && <div className="form-page"><span className="section-kicker">۰۳ / سبک تمرین</span><h2>برنامه رو با زندگی‌ات هماهنگ کنیم</h2><div className="form-grid"><label>روزهای تمرین در هفته<select data-testid="profile-days" value={profileDraft.days} onChange={e=>updateProfile('days',Number(e.target.value))}>{[1,2,3,4,5,6].map(n=><option value={n} key={n}>{fa(n)} روز</option>)}</select></label><label>زمان هر جلسه<select data-testid="profile-minutes" value={profileDraft.minutes} onChange={e=>updateProfile('minutes',Number(e.target.value))}>{[20,30,45,60].map(n=><option value={n} key={n}>{fa(n)} دقیقه</option>)}</select></label></div><div className="field-block"><strong>محل تمرین</strong><div className="choice-grid">{['خانه','باشگاه'].map(x=><button data-testid={`place-${x}`} className={`choice ${profileDraft.place===x?'chosen':''}`} key={x} onClick={()=>updateProfile('place',x)}>{x}</button>)}</div></div><div className="field-block"><strong>تجهیزات در دسترس</strong><div className="choice-grid">{['بدون وسیله','دمبل','کش'].map(x=><button data-testid={`equipment-${x}`} className={`choice ${profileDraft.equipment.includes(x)?'chosen':''}`} key={x} onClick={()=>toggleValue('equipment',x)}>{x}</button>)}</div></div><div className="field-block"><strong>عضلات مورد علاقه برای تقویت</strong><div className="choice-grid">{focusList.map(x=><button data-testid={`focus-${x}`} className={`choice ${profileDraft.focus.includes(x)?'chosen':''}`} key={x} onClick={()=>toggleValue('focus',x)}>{x}</button>)}</div></div></div>}{step===3 && <div className="form-page"><span className="section-kicker">۰۴ / سلامت و ترجیحات</span><h2>با خیال راحت شروع کن</h2><p className="muted">ناحیه‌های آسیب‌دیده از برنامهٔ پیشنهادی کنار گذاشته می‌شن؛ در صورت درد یا آسیب، با متخصص مشورت کن.</p><div className="field-block"><strong>محدودیت یا آسیب‌دیدگی (در صورت وجود)</strong><div className="choice-grid">{injuries.map(x=><button data-testid={`injury-${x}`} className={`choice ${profileDraft.injury.includes(x)?'chosen':''}`} key={x} onClick={()=>toggleValue('injury',x)}>{x}</button>)}</div></div><label className="full-label">حساسیت‌ها و ترجیحات غذایی<input data-testid="profile-dietary" placeholder="مثلاً گیاه‌خوار، حساسیت به لبنیات..." value={profileDraft.dietary} onChange={e=>updateProfile('dietary',e.target.value)}/></label><div className="form-grid"><label>کیفیت خواب (اختیاری)<select data-testid="profile-sleep" value={profileDraft.sleep} onChange={e=>updateProfile('sleep',e.target.value)}><option value="">ثبت نمی‌کنم</option><option>خوب</option><option>متوسط</option><option>کم</option></select></label><label>فعالیت روزانه (اختیاری)<select data-testid="profile-activity" value={profileDraft.activity} onChange={e=>updateProfile('activity',e.target.value)}><option value="">ثبت نمی‌کنم</option><option>کم‌تحرک</option><option>معمولی</option><option>پرتحرک</option></select></label></div></div>}<div className="form-actions">{step>0?<button className="btn-ghost" data-testid="assessment-back" onClick={()=>setStep(step-1)}><ArrowRight size={17}/>قبلی</button>:profile?<button className="btn-ghost" data-testid="assessment-cancel" onClick={()=>navigate('home')}>انصراف</button>:<span/>}<button className="btn-primary" data-testid={step===3?'assessment-save':'assessment-next'} onClick={()=>{if(step===0 && (!profileDraft.gender || profileDraft.age<12 || profileDraft.age>100 || profileDraft.height<100 || profileDraft.height>240 || profileDraft.weight<25 || profileDraft.weight>300)) return; if(step<3)setStep(step+1);else saveProfile()}}>{step===3?'ساخت برنامه من':'ادامه'}<ArrowLeft size={17}/></button></div>{step===0 && (!profileDraft.gender || profileDraft.age<12 || profileDraft.age>100 || profileDraft.height<100 || profileDraft.height>240 || profileDraft.weight<25 || profileDraft.weight>300) && <p className="validation" data-testid="assessment-validation">جنسیت را انتخاب کن و سن، قد و وزن را در بازهٔ معتبر وارد کن.</p>}</div></div></main> : <main className="container page-content">
      {view==='home' && <><div className="hero"><div className="hero-photo"/><div className="hero-shade"/><div className="hero-content"><div className="hero-topline"><span className="hero-logo">DUEL<span>FIT</span></span><span className="hero-badge"><span className="live-dot"/> سطح {levelLabel}</span></div><div className="hero-copy"><div className="eyebrow"><span className="slash"/> هر روز، یک قدم قوی‌تر</div><h1>وقتشه روی <em>خودت</em><br/> سرمایه‌گذاری کنی.</h1><p>{trainedToday?'آفرین! تمرین امروزت ثبت شد. برای بازیابی بدنت وقت بذار.':isScheduled?'برنامهٔ امروزت آماده‌ست؛ با سرعت خودت شروع کن.':'امروز در برنامه‌ات روز استراحت است؛ اگر آماده‌ای، می‌تونی یک جلسهٔ سبک انجام بدی.'}</p><button className="btn-primary hero-cta" data-testid="home-start-training" onClick={()=>navigate('training')}>{trainedToday?'دیدن برنامه':'شروع تمرین'}<ArrowLeft size={18}/></button></div><div className="hero-foot"><span><CalendarDays size={16}/>{new Intl.DateTimeFormat('fa-IR',{weekday:'long',day:'numeric',month:'long'}).format(new Date())}</span><span><Clock3 size={16}/>{plan ? `${fa(plan.duration)} دقیقه پیشنهادی` : '—'}</span></div></div></div><div className="section-head"><div><span className="section-kicker">داشبورد شخصی</span><h2>امروز چطور پیش می‌ره؟</h2></div><button data-testid="home-history-link" className="text-link" onClick={()=>navigate('history')}>تاریخچه <ArrowLeft size={16}/></button></div><div className="overview-grid"><div className="overview-card"><span className="overview-icon green"><Dumbbell size={21}/></span><span>جلسات این هفته</span><strong data-testid="home-weekly-sessions">{fa(weekly.length)} <small>/ {fa(profile?.days || 0)}</small></strong><div className="mini-progress"><span style={{width:`${Math.min(100,weekly.length/(profile?.days||1)*100)}%`}}/></div></div><div className="overview-card"><span className="overview-icon dark"><Clock3 size={21}/></span><span>زمان تمرین کل</span><strong data-testid="home-total-minutes">{fa(totalMinutes)} <small>دقیقه</small></strong><p>بر اساس جلسه‌های ثبت‌شده</p></div><div className="overview-card"><span className="overview-icon dark"><Target size={21}/></span><span>هدف اصلی</span><strong className="goal-name" data-testid="home-main-goal">{profile?.goal}</strong><p>{profile?.days ? `${fa(profile.days)} روز تمرین در هفته` : ''}</p></div></div><div className="split-section"><section className="today-panel"><div className="panel-heading"><div><span className="section-kicker">برنامه شخصی تو</span><h2>{isScheduled?'تمرین امروز':'جلسهٔ بعدی'}</h2></div><span className="small-pill">{trainedToday?'ثبت‌شده':isScheduled?'روز تمرین':'روز استراحت'}</span></div>{plan && plan.chosen.length ? <><div className="today-visual"><span className="workout-orb"><Dumbbell size={30}/></span><div><strong>{profile?.goal === 'افزایش استقامت'?'تمرین ترکیبی':'تمرین تمام‌بدن'}</strong><span>{fa(plan.chosen.length)} حرکت · {fa(plan.duration)} دقیقه · {fa(plan.sets)} ست</span></div></div><div className="exercise-preview">{plan.chosen.slice(0,3).map((e,i)=><div key={e.id}><span className="preview-number">{String(i+1).padStart(2,'0')}</span><span>{e.name}</span><small>{fa(plan.sets)} × {fa(e.type==='time'?Math.max(15,Math.min(profile?.plank||20,60)):plan.reps)} {e.type==='time'?'ثانیه':'تکرار'}</small></div>)}</div><button className="panel-action" data-testid="home-view-plan" onClick={()=>navigate('training')}>مشاهده برنامه کامل <ArrowLeft size={18}/></button></>:<div className="empty-state">با محدودیت‌های فعلی، حرکت ایمنی برای پیشنهاد پیدا نشد. با متخصص مشورت کن و ارزیابی را ویرایش کن.</div>}</section><section className="quick-panel"><div className="panel-heading"><div><span className="section-kicker">همه چیز در دسترس</span><h2>مسیر خودت رو بساز</h2></div></div><div className="quick-grid">{([['library','کتابخانه حرکات','آموزش و نکات ایمنی',Dumbbell],['nutrition','تغذیه و آب','ثبت روزانه',Leaf],['stretch','قد و کشش','تحرک و انعطاف',Waves],['goals','اهداف شخصی','پیگیری مسیر',Target],['body','نقشه بدن','عضلات فعال',Activity],['stats','آمار و پیشرفت','گزارش واقعی',TrendingUp],['history','تاریخچه تمرین','جلسات ثبت‌شده',History],['records','رکورد شنا و دمبل','شمارش با دوربین',Dumbbell],['photos','تغییر من','عکس قبل و بعد',Activity],['settings','تنظیمات','اطلاعات و حریم خصوصی',Settings2]] as const).map(([v,label,sub,Icon])=><button key={v} data-testid={`home-link-${v}`} className="quick-item" onClick={()=>navigate(v)}><span className="quick-icon"><Icon size={20}/></span><span><strong>{label}</strong><small>{sub}</small></span><ChevronLeft size={17} className="quick-arrow"/></button>)}</div></section></div><div className="notice-strip"><Info size={19}/><span>این برنامه براساس اطلاعاتی که وارد کردی تنظیم می‌شه؛ تمرین انجام‌نشده به‌صورت خودکار ثبت نمی‌شه.</span><button data-testid="home-edit-profile" onClick={()=>{setProfileDraft(profile||initialProfile);setStep(0);navigate('assessment')}}>ویرایش ارزیابی</button></div></>}
      {view==='training' && <><PageHeading kicker="برنامهٔ تو" title="قدم‌به‌قدم، قوی‌تر" desc="جلسه‌ات بر اساس سطح، توان، زمان آزاد، امکانات و نتیجهٔ تمرین‌های قبلی تنظیم شده."/><div className="training-layout"><div><div className="workout-header"><div><span className="section-kicker">جلسهٔ پیشنهادی</span><h2>تمرین تمام‌بدن</h2><p>{plan?.recovering?'چون جلسهٔ قبل سخت بوده، فشار امروز کمتره.':plan?.progressing?'با توجه به دو جلسهٔ آسان قبلی، تعداد ست‌ها کمی افزایش یافته.':'از پایه شروع می‌کنیم و با ثبت نتیجه، برنامه را تنظیم می‌کنیم.'}</p></div><div className="workout-header-icon"><Dumbbell size={32}/></div></div><div className="workout-metrics"><span><Clock3 size={17}/>{fa(plan?.duration||0)} دقیقه</span><span><Activity size={17}/>{fa(plan?.chosen.length||0)} حرکت</span><span><RotateCcw size={17}/>{fa(plan?.rest||0)} ثانیه استراحت</span></div>{plan?.chosen.length ? <div className="exercise-list">{plan.chosen.map((e,i)=><button className="exercise-row" data-testid={`plan-exercise-${e.id}`} key={e.id} onClick={()=>setSelectedExercise(e)}><span className="exercise-glyph">{e.icon}</span><span className="exercise-info"><small>حرکت {fa(i+1)} · {e.muscle}</small><strong>{e.name}</strong><em>{fa(plan.sets)} ست × {fa(e.type==='time'?Math.max(15,Math.min(profile?.plank||20,60)):plan.reps)} {e.type==='time'?'ثانیه':'تکرار'}</em></span><ChevronLeft size={19}/></button>)}</div>:<div className="empty-state">با توجه به آسیب‌های انتخاب‌شده، حرکت ایمنی برای پیشنهاد باقی نمانده. ارزیابی رو ویرایش کن یا از متخصص راهنمایی بگیر.</div>}<button className="btn-primary full-button" data-testid="training-start-session" disabled={!plan?.chosen.length} onClick={startSession}>شروع و ثبت جلسه <ArrowLeft size={18}/></button><div className="camera-plan-actions">{plan?.chosen.some(e=>e.id==='pushup'||e.id==='knee-pushup'||e.id==='incline-pushup') && <button data-testid="plan-camera-pushup" className="panel-action" onClick={()=>openCamera('pushup',plan.reps)}>اجرای شنا با دوربین · هدف {fa(plan.reps)} تکرار</button>}{plan?.chosen.some(e=>e.id==='curl') && <button data-testid="plan-camera-curl" className="panel-action" onClick={()=>openCamera('curl',plan.reps)}>اجرای جلو بازو با دوربین · هدف {fa(plan.reps)} تکرار</button>}</div><p className="under-button">ثبت دستی برای همهٔ حرکات؛ تشخیص دوربینی فقط برای شنا و جلو بازو دمبل در دسترس است.</p></div><aside className="training-side"><div className="side-card"><span className="side-icon"><Flame size={22}/></span><h3>آماده‌سازی بدن</h3><p>قبل از شروع، ۵ دقیقه راه رفتن آرام و حرکت ملایم مفاصل انجام بده. بعد از تمرین هم سرعت رو کم کن و کشش ملایم داشته باش.</p></div><div className="side-card"><span className="side-icon"><Heart size={22}/></span><h3>به بدنت گوش بده</h3><p>بین ست‌ها {fa(plan?.rest||90)} ثانیه استراحت کن. اگر درد غیرعادی داری، حرکت رو متوقف کن. برای هر عضله حدود ۴۸ ساعت ریکاوری در نظر بگیر.</p></div><button className="side-link" data-testid="training-library-link" onClick={()=>navigate('library')}>دیدن کتابخانهٔ حرکت‌ها <ArrowLeft size={17}/></button></aside></div></>}
      {view==='library' && <><PageHeading kicker="یادگیری حرکت" title="کتابخانه تمرین‌ها" desc="هر حرکت را با شیوهٔ اجرا، اشتباه رایج و جایگزین مناسب بشناس."/><div className="filter-row">{groups.map(g=><button data-testid={`library-filter-${g}`} key={g} className={category===g?'selected':''} onClick={()=>setCategory(g)}>{g}</button>)}</div><div className="library-grid">{exercises.filter(e=>category==='همه'||e.group===category).map(e=><button data-testid={`library-exercise-${e.id}`} className="library-card" key={e.id} onClick={()=>setSelectedExercise(e)}><span className="library-icon">{e.icon}</span><span className="library-meta">{e.group} · {e.gear}</span><strong>{e.name}</strong><span className="library-bottom">{['','مبتدی','متوسط','پیشرفته'][e.level]} <ArrowLeft size={16}/></span></button>)}</div></>}
      {view==='history' && <><PageHeading kicker="گزارش واقعی" title="تاریخچه تمرین‌ها" desc="فقط جلسه‌هایی که خودت ثبت کردی اینجا نمایش داده می‌شن."/>{data.sessions.length ? <div className="history-list">{data.sessions.map(s=><article className="history-card" key={s.id}><div className="history-date"><span><Check size={19}/></span><div><strong>{dateFa(s.date)}</strong><small>{s.source==='camera'?'ثبت دوربینی (تقریبی)':'ثبت دستی'} · {s.minutes ? `${fa(s.minutes)} دقیقه` : `${fa(s.exercises[0]?.reps||0)} تکرار`}</small></div></div><div className="history-items">{s.exercises.map(x=><span key={x.id}>{exercises.find(e=>e.id===x.id)?.name || x.id}: {s.source==='camera'?`${fa(x.reps)} تکرار`:`${fa(x.done)} ست`}</span>)}</div><div className="history-foot">سختی جلسه: {['','خیلی آسان','آسان','متوسط','سخت','خیلی سخت'][s.effort]}{s.note&&<span> · {s.note}</span>}</div><button className="delete-link" data-testid={`delete-session-${s.id}`} onClick={()=>setData(d=>({...d,sessions:d.sessions.filter(x=>x.id!==s.id)}))}>حذف این ثبت</button></article>)}</div>:<Empty icon={<History size={28}/>} title="هنوز تمرینی ثبت نشده" desc="اولین جلسه‌ات را از برنامه تمرینی شروع و بعد از انجام، ثبت کن." action="دیدن برنامه تمرینی" onAction={()=>navigate('training')}/>}</>}
      {view==='records' && <><PageHeading kicker="چالش شخصی" title="رکورد شنا و دمبل" desc="هر روز با دوربین تمرین کن؛ فقط تکرارهای تشخیص‌داده‌شده‌ای که تأیید می‌کنی ثبت می‌شوند."/><div className="record-grid">{([['pushup','شنا معمولی','pushup'],['curl','جلو بازو دمبل','curl']] as const).map(([id,label,mode])=>{const entries=data.sessions.filter(s=>s.source==='camera'&&s.exercises.some(x=>x.id===id));const best=Math.max(0,...entries.map(s=>s.exercises.find(x=>x.id===id)?.reps||0));const todayCount=entries.filter(s=>s.date===today).reduce((n,s)=>n+(s.exercises.find(x=>x.id===id)?.reps||0),0);return <section key={id} className="surface-card record-card"><span className="side-icon"><Dumbbell size={22}/></span><h2>{label}</h2><div className="record-numbers"><div><strong data-testid={`record-best-${id}`}>{fa(best)}</strong><small>بهترین رکورد جلسه</small></div><div><strong data-testid={`record-today-${id}`}>{fa(todayCount)}</strong><small>تکرار امروز</small></div></div><button className="btn-primary full-button" data-testid={`record-camera-${id}`} onClick={()=>openCamera(mode)}><Activity size={18}/> شروع با دوربین</button></section>})}</div><p className="inline-note">تشخیص دوربینی می‌تواند خطا داشته باشد؛ رکوردها ثبت خودکارِ تقریبی‌اند، نه تأیید قطعی فرم توسط مربی. در صورت درد تمرین را متوقف کن.</p></>}
      {view==='photos' && <><PageHeading kicker="مسیر تغییر" title="تغییر من" desc="عکس شروع و پایان دوره را کنار هم ببین؛ بدون ادعای درصد تغییر یا تحلیل ساختگی."/><ProgressPhotos/></>}
      {view==='body' && <><PageHeading kicker="فعالیت عضلات" title="نقشهٔ تمرین بدن" desc="نمایش ناحیه‌های تمرین‌داده‌شده بر اساس جلسه‌های ثبت‌شده؛ این داده نشانهٔ رشد عضله نیست."/><div className="body-layout"><div className="body-map-card"><div className="body-map-top"><span>ناحیه‌های فعال</span><span>بر اساس ثبت‌های شما</span></div><div className="body-visual" aria-label="نقشه ساده فعالیت عضلات"><svg viewBox="0 0 220 380" role="img" aria-label="طرح شماتیک بدن انسان"><circle cx="110" cy="35" r="24" fill="#29342d"/><path d="M78 65 Q65 64 51 80 L31 158 Q28 169 38 173 Q48 175 52 166 L75 111 L80 175 L72 207 L80 345 Q81 360 94 360 Q104 360 105 347 L109 235 L114 347 Q116 360 128 360 Q140 360 140 347 L147 207 L139 175 L144 111 L168 166 Q173 177 184 172 Q193 167 188 155 L169 80 Q156 64 142 65Z" fill="#1e2822" stroke="#47564b" strokeWidth="2"/><path d="M78 72 Q110 91 142 72 L139 127 Q111 144 81 127Z" fill={data.sessions.some(s=>s.exercises.some(x=>['سینه','پشت','سرشانه','بازو'].includes(exercises.find(e=>e.id===x.id)?.muscle||'')))?'#b7fb54':'#354438'} opacity=".8"/><path d="M82 133 Q110 145 138 133 L143 190 L78 190Z" fill={data.sessions.some(s=>s.exercises.some(x=>exercises.find(e=>e.id===x.id)?.muscle==='میان‌تنه'))?'#b7fb54':'#354438'} opacity=".75"/><path d="M78 202 L107 209 L103 327 L80 327Z M113 209 L143 202 L138 327 L116 327Z" fill={data.sessions.some(s=>s.exercises.some(x=>exercises.find(e=>e.id===x.id)?.muscle==='پا'))?'#b7fb54':'#354438'} opacity=".8"/></svg></div><p className="map-caption"><Info size={16}/>این یک نقشهٔ شماتیک دوبعدی از فعالیت ثبت‌شده است، نه تحلیل سه‌بعدی یا اندازه‌گیری عضله.</p></div><div className="muscle-panel"><h2>گزارش ناحیه‌ها</h2><p className="muted">تعداد جلسه‌هایی که هر ناحیه در آن تمرین شده</p>{['سینه','پشت','پا','میان‌تنه','سرشانه','بازو'].map(m=>{const count=data.sessions.filter(s=>s.exercises.some(x=>exercises.find(e=>e.id===x.id)?.muscle===m)).length; return <div className="muscle-row" data-testid={`muscle-${m}`} key={m}><span className={count?'muscle-dot on':'muscle-dot'}/><strong>{m}</strong><span>{fa(count)} جلسه</span></div>})}<div className="inline-note"><CircleHelp size={18}/> مدل سه‌بعدی چرخان و انتخاب جزءبه‌جزء عضلات هنوز اضافه نشده است.</div></div></div></>}
      {view==='nutrition' && <><PageHeading kicker="مراقبت روزانه" title="تغذیه و آب" desc="وعده‌ها و آب مصرفی را ثبت کن؛ محاسبهٔ کالری و شناسایی غذا از تصویر هنوز در دسترس نیست."/><div className="nutrition-layout"><section className="surface-card"><div className="card-title"><span className="side-icon"><Waves size={21}/></span><div><h2>آب امروز</h2><p>{dateFa(today)}</p></div></div><div className="water-big" data-testid="water-count">{fa(data.water[today]||0)} <small>لیوان</small></div><div className="water-controls"><button data-testid="water-minus" aria-label="کم کردن یک لیوان آب" onClick={()=>setData(d=>({...d,water:{...d.water,[today]:Math.max(0,(d.water[today]||0)-1)}}))}><Minus size={19}/></button><button data-testid="water-plus" className="btn-primary" onClick={()=>setData(d=>({...d,water:{...d.water,[today]:(d.water[today]||0)+1}}))}><Plus size={18}/> ثبت یک لیوان</button></div><p className="muted">نیاز بدن به آب برای هر فرد متفاوت است؛ این بخش فقط مصرف ثبت‌شده را نشان می‌دهد.</p></section><section className="surface-card"><div className="card-title"><span className="side-icon"><Leaf size={21}/></span><div><h2>ثبت وعده غذایی</h2><p>یادداشت شخصی امروز</p></div></div><label>وعده<select data-testid="food-meal" value={meal} onChange={e=>setMeal(e.target.value)}>{['صبحانه','میان‌وعده','ناهار','عصرانه','شام'].map(x=><option key={x}>{x}</option>)}</select></label><label>چه چیزی خوردی؟<input data-testid="food-text" placeholder="مثلاً برنج، مرغ و سالاد" value={foodText} onChange={e=>setFoodText(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')addFood()}}/></label><button className="btn-primary full-button" data-testid="food-add" onClick={addFood} disabled={!foodText.trim()}><Plus size={18}/> ثبت وعده</button></section></div><section className="surface-card food-list-card"><h2>وعده‌های امروز</h2>{data.foods.filter(f=>f.date===today).length?data.foods.filter(f=>f.date===today).map(f=><div className="food-entry" data-testid={`food-entry-${f.id}`} key={f.id}><span className="food-entry-icon"><Leaf size={17}/></span><div><strong>{f.meal}</strong><span>{f.text}</span></div><button data-testid={`food-delete-${f.id}`} aria-label="حذف وعده" onClick={()=>setData(d=>({...d,foods:d.foods.filter(x=>x.id!==f.id)}))}><X size={17}/></button></div>):<div className="empty-inline">هنوز وعده‌ای برای امروز ثبت نکردی.</div>}</section><div className="inline-note nutrition-note"><Info size={18}/> از روی نام غذا، مقدار کالری قابل اعتماد نیست. تا زمان اتصال به دادهٔ معتبر تغذیه، عددی حدس نمی‌زنیم.</div></>}
      {view==='stats' && <><PageHeading kicker="آنچه واقعاً انجام دادی" title="آمار و پیشرفت" desc="همهٔ عددها فقط از ثبت‌های خودت محاسبه می‌شن."/><div className="stats-grid"><div className="stat-tile"><span><Dumbbell size={20}/></span><strong data-testid="stats-sessions">{fa(data.sessions.length)}</strong><small>جلسه ثبت‌شده</small></div><div className="stat-tile"><span><Clock3 size={20}/></span><strong data-testid="stats-minutes">{fa(totalMinutes)}</strong><small>دقیقه تمرین</small></div><div className="stat-tile"><span><BadgeCheck size={20}/></span><strong data-testid="stats-sets">{fa(totalSets)}</strong><small>ست ثبت‌شده</small></div><div className="stat-tile"><span><Flame size={20}/></span><strong data-testid="stats-weekly">{fa(weekly.length)}</strong><small>جلسه این هفته</small></div></div><div className="stats-layout"><section className="surface-card"><div className="panel-heading"><div><span className="section-kicker">هفت روز گذشته</span><h2>فعالیت تمرینی</h2></div></div><div className="chart" data-testid="stats-chart">{Array.from({length:7},(_,i)=>{const d=new Date(); d.setDate(d.getDate()-6+i); const count=data.sessions.filter(s=>s.date===dateKey(d)).length; return <div className="chart-col" key={i}><div className="chart-bar-area"><div className={`chart-bar ${count?'has-data':''}`} style={{height:`${count?Math.min(100,Math.max(18,count*34)):3}%`}} title={`${fa(count)} جلسه`}/></div><span>{weekDays[jsToFaDay(d)].slice(0,1)}</span></div>})}</div>{!data.sessions.length&&<p className="empty-chart">هنوز داده‌ای برای نمایش نیست. بعد از ثبت اولین جلسه، نمودار شکل می‌گیره.</p>}</section><section className="surface-card"><div className="panel-heading"><div><span className="section-kicker">اندازه‌گیری شخصی</span><h2>روند وزن</h2></div></div>{data.weightLogs.length?<div className="weight-list">{data.weightLogs.slice(-5).reverse().map((x,i)=><div key={i}><span>{dateFa(x.date)}</span><strong>{fa(x.value)} کیلوگرم</strong></div>)}</div>:<p className="empty-chart">هنوز وزنی ثبت نشده.</p>}<div className="weight-form"><input data-testid="weight-input" type="number" min="25" max="300" step="0.1" placeholder="وزن امروز (کیلوگرم)" value={weightValue} onChange={e=>setWeightValue(e.target.value)}/><button data-testid="weight-save" onClick={()=>{const n=Number(weightValue);if(n>=25&&n<=300){setData(d=>({...d,weightLogs:[...d.weightLogs,{date:today,value:n}]}));setWeightValue('')}}}>ثبت وزن</button></div></section></div><button data-testid="stats-goals-link" className="panel-action stats-goal-link" onClick={()=>navigate('goals')}>مشاهده اهداف شخصی <ArrowLeft size={17}/></button></>}
      {view==='goals' && <><PageHeading kicker="مسیر شخصی" title="اهداف من" desc="پیشرفت هدف تمرینی فقط با جلسه‌های ثبت‌شده به‌روزرسانی می‌شه."/><div className="goals-layout"><section className="surface-card"><h2>هدف جدید</h2><label>نوع هدف<select data-testid="goal-type" value={goalTitle} onChange={e=>setGoalTitle(e.target.value)}><option>تعداد جلسه تمرین</option><option>وزن هدف</option></select></label><label>مقدار هدف<input data-testid="goal-target" type="number" min="1" value={goalTarget} onChange={e=>setGoalTarget(e.target.value)}/></label><label>مهلت<input data-testid="goal-deadline" type="date" min={today} value={goalDeadline} onChange={e=>setGoalDeadline(e.target.value)}/></label><button className="btn-primary full-button" data-testid="goal-add" disabled={!goalDeadline||Number(goalTarget)<=0} onClick={addGoal}><Plus size={18}/> افزودن هدف</button></section><section className="goals-list">{data.goals.length?data.goals.map(g=>{const current=g.title==='تعداد جلسه تمرین'?data.sessions.filter(s=>s.date<=g.deadline).length:(data.weightLogs.at(-1)?.value||0);const percent=g.title==='تعداد جلسه تمرین'?Math.min(100,current/g.target*100):0;return <div className="surface-card goal-card" data-testid={`goal-${g.id}`} key={g.id}><div className="goal-card-top"><span className="side-icon"><Target size={20}/></span><button data-testid={`goal-delete-${g.id}`} onClick={()=>setData(d=>({...d,goals:d.goals.filter(x=>x.id!==g.id)}))} aria-label="حذف هدف"><X size={17}/></button></div><h3>{g.title}</h3><p>{g.title==='تعداد جلسه تمرین'?`${fa(current)} از ${fa(g.target)} ${g.unit}`:`آخرین وزن ثبت‌شده: ${current?fa(current)+' کیلوگرم':'هنوز ثبت نشده'} · هدف: ${fa(g.target)} کیلوگرم`}</p>{g.title==='تعداد جلسه تمرین'&&<div className="mini-progress"><span style={{width:`${percent}%`}}/></div>}<small>مهلت: {dateFa(g.deadline)}</small></div>}):<Empty icon={<Target size={28}/>} title="هنوز هدفی نداری" desc="یک هدف قابل اندازه‌گیری تعریف کن تا مسیرت مشخص‌تر بشه."/>}</section></div></>}
      {view==='stretch' && <><PageHeading kicker="تحرک و بازیابی" title="قد و کشش" desc="حرکات ملایم برای انعطاف‌پذیری و وضعیت بدن؛ افزایش قد استخوانی را تضمین نمی‌کنند."/><div className="stretch-intro"><Waves size={30}/><div><h2>کمی برای حرکت بهتر وقت بذار</h2><p>آرام شروع کن، نفس رو حبس نکن و هر کشش رو فقط تا حد راحتی انجام بده. در صورت درد حرکت رو متوقف کن.</p></div></div><div className="library-grid">{exercises.filter(e=>e.group==='کشش').map(e=><button className="library-card" data-testid={`stretch-${e.id}`} key={e.id} onClick={()=>setSelectedExercise(e)}><span className="library-icon">{e.icon}</span><span className="library-meta">کشش و تحرک</span><strong>{e.name}</strong><span className="library-bottom">دیدن آموزش <ArrowLeft size={16}/></span></button>)}</div><div className="inline-note"><Info size={18}/> برای اندازه‌گیری تغییرات قد، ثبت تاریخ‌دار قد و نمودار هنوز اضافه نشده است.</div></>}
      {view==='settings' && <><PageHeading kicker="کنترل اطلاعات" title="تنظیمات" desc="اطلاعات فعلاً روی همین دستگاه ذخیره می‌شن و با دستگاه‌های دیگر همگام نمی‌شن."/><div className="settings-layout"><section className="surface-card"><h2>اطلاعات شخصی</h2><p className="muted">سن، هدف، سطح و محدودیت‌هایت را هر زمان خواستی به‌روز کن.</p><button className="settings-row" data-testid="settings-edit-assessment" onClick={()=>{setProfileDraft(profile||initialProfile);setStep(0);navigate('assessment')}}><UserRound size={20}/>ویرایش و ارزیابی مجدد<ChevronLeft size={18}/></button><button className="settings-row" data-testid="settings-history" onClick={()=>navigate('history')}><History size={20}/>تاریخچه تمرین‌ها<ChevronLeft size={18}/></button></section><section className="surface-card"><h2>حریم خصوصی</h2><p className="muted">دوربین تمرین فقط با اجازهٔ تو روشن می‌شود و تصویر تمرین ذخیره یا ارسال نمی‌شود. عکس‌های بخش تغییر من فقط پس از انتخاب تو بارگذاری می‌شوند.</p><button className="settings-row danger-row" data-testid="settings-delete-data" onClick={()=>setConfirmDelete(true)}><X size={20}/>پاک کردن تمام اطلاعات<ChevronLeft size={18}/></button><div className="inline-note"><Info size={18}/> تنظیمات گرافیکی پیشرفته و همگام‌سازی زمانی اضافه می‌شوند که قابلیت‌های مربوط به آن‌ها واقعاً پیاده‌سازی شده باشند.</div></section></div></>}
    </main>}
    {view!=='assessment'&&<><footer className="footer container"><span>DUEL<span>FIT</span> · پیشرفت شخصی، بدون مقایسه</span><span>ساخته‌شده برای مسیر واقعی تو</span></footer><nav className="bottom-nav" aria-label="منوی اصلی">{([['home','خانه',Home],['training','تمرین',Dumbbell],['body','بدن',Activity],['nutrition','تغذیه',Leaf],['stats','آمار',TrendingUp]] as const).map(([v,label,Icon])=><button key={v} data-testid={`nav-${v}`} className={view===v?'active':''} onClick={()=>navigate(v)}><Icon size={21} strokeWidth={view===v?2.5:1.8}/><span>{label}</span></button>)}</nav></>}
    {selectedExercise&&<div className="modal-backdrop" onClick={()=>setSelectedExercise(null)}><div className="detail-modal" role="dialog" aria-modal="true" aria-label={selectedExercise.name} onClick={e=>e.stopPropagation()}><button className="modal-close" data-testid="exercise-close" onClick={()=>setSelectedExercise(null)}><X size={20}/></button><div className="detail-art"><span>{selectedExercise.icon}</span><small>{selectedExercise.group}</small></div><div className="detail-content"><span className="section-kicker">راهنمای حرکت</span><h2>{selectedExercise.name}</h2><div className="detail-tags"><span>{selectedExercise.muscle}</span><span>{selectedExercise.gear}</span><span>{['','مبتدی','متوسط','پیشرفته'][selectedExercise.level]}</span></div><h3>چطور انجامش بدی؟</h3><p>{selectedExercise.how}</p><h3>اشتباه رایج</h3><p>{selectedExercise.mistake}</p><h3>جایگزین و بازیابی</h3><p>جایگزین: {selectedExercise.alternative} · استراحت پیشنهادی: {selectedExercise.recovery}</p><div className="inline-note"><Info size={18}/>این راهنمای متنی است؛ آموزش تصویری و تحلیل دوربینی هنوز پیاده‌سازی نشده‌اند.</div></div></div></div>}
    {sessionOpen&&plan&&<div className="modal-backdrop" onClick={()=>setSessionOpen(false)}><div className="session-modal" role="dialog" aria-modal="true" aria-label="ثبت جلسه تمرینی" onClick={e=>e.stopPropagation()}><div className="session-top"><div><span className="section-kicker">ثبت دستی تمرین</span><h2>جلسه امروز</h2></div><button data-testid="session-close" onClick={()=>setSessionOpen(false)} aria-label="بستن"><X size={21}/></button></div><p className="muted">فقط ست‌هایی رو علامت بزن که واقعاً انجام دادی. هر حرکت حداکثر {fa(plan.sets)} ست داره.</p><div className="session-exercises">{plan.chosen.map(e=><div className="session-exercise" key={e.id}><div><strong>{e.name}</strong><small>{fa(plan.sets)} ست × {fa(e.type==='time'?Math.max(15,Math.min(profile?.plank||20,60)):plan.reps)} {e.type==='time'?'ثانیه':'تکرار'}</small></div><div className="stepper"><button data-testid={`session-minus-${e.id}`} aria-label={`کاهش ست ${e.name}`} onClick={()=>setChecks(c=>({...c,[e.id]:Math.max(0,(c[e.id]||0)-1)}))}><Minus size={16}/></button><span data-testid={`session-count-${e.id}`}>{fa(checks[e.id]||0)}</span><button data-testid={`session-plus-${e.id}`} aria-label={`افزایش ست ${e.name}`} onClick={()=>setChecks(c=>({...c,[e.id]:Math.min(plan.sets,(c[e.id]||0)+1)}))}><Plus size={16}/></button></div></div>)}</div><div className="effort-box"><strong>سختی این جلسه چقدر بود؟</strong><div className="effort-options">{[1,2,3,4,5].map(n=><button key={n} data-testid={`session-effort-${n}`} className={effort===n?'active':''} onClick={()=>setEffort(n)}>{fa(n)}</button>)}</div><small>۱ خیلی آسان · ۳ متوسط · ۵ خیلی سخت</small></div><textarea data-testid="session-note" placeholder="یادداشت کوتاه (اختیاری)" value={sessionNote} onChange={e=>setSessionNote(e.target.value)} /><button className="btn-primary full-button" data-testid="session-save" disabled={!Object.values(checks).some(n=>n>0)} onClick={saveSession}><Save size={18}/> ثبت تمرین‌های انجام‌شده</button></div></div>}
    {cameraMode && <Suspense fallback={<div className="modal-backdrop"><div className="surface-card">در حال آماده‌سازی دوربین…</div></div>}><CameraWorkout key={cameraMode} mode={cameraMode} target={cameraTarget} onSave={saveCamera} onClose={()=>setCameraMode(null)}/></Suspense>}
    {confirmDelete&&<div className="modal-backdrop" onClick={()=>setConfirmDelete(false)}><div className="confirm-modal" role="dialog" aria-modal="true" onClick={e=>e.stopPropagation()}><h2>همهٔ اطلاعات پاک بشن؟</h2><p>ارزیابی، جلسه‌ها، وعده‌ها و هدف‌ها برای همیشه از این دستگاه حذف می‌شن. عکس‌های بارگذاری‌شده را جداگانه از بخش «تغییر من» حذف کن. این کار قابل بازگشت نیست.</p><div><button data-testid="delete-cancel" className="btn-ghost" onClick={()=>setConfirmDelete(false)}>انصراف</button><button data-testid="delete-confirm" className="danger-btn" onClick={()=>{setData(empty);setProfileDraft(initialProfile);setStep(0);setConfirmDelete(false);navigate('assessment')}}>بله، پاک کن</button></div></div></div>}
  </div>;
}
function PageHeading({kicker,title,desc}:{kicker:string;title:string;desc:string}){return <div className="page-heading"><span className="section-kicker">{kicker}</span><h1>{title}</h1><p>{desc}</p></div>}
function Empty({icon,title,desc,action,onAction}:{icon:React.ReactNode;title:string;desc:string;action?:string;onAction?:()=>void}){return <div className="empty-state large"><span className="empty-icon">{icon}</span><h3>{title}</h3><p>{desc}</p>{action&&<button data-testid="empty-action" className="btn-primary" onClick={onAction}>{action}<ArrowLeft size={17}/></button>}</div>}
export default App;
